	JLE     sequenceDecs_decode_bmi2_fill_2_check_overread
	CMPQ    DX, $0x07
	JLE     sequenceDecs_decode_bmi2_fill_2_end
	SHLQ    $0x08, AX
	SUBQ    $0x01, R13
	SUBQ    $0x01, BX
	SUBQ    $0x08, DX
	MOVBQZX (R13), CX
	ORQ     CX, AX
	JMP     sequenceDecs_decode_bmi2_fill_2_byte_by_byte

sequenceDecs_decode_bmi2_fill_2_check_overread:
	CMPQ DX, $0x40
	JA   error_overread

sequenceDecs_decode_bmi2_fill_2_end:
	// Update literal length
	MOVQ   $0x00000808, CX
	BEXTRQ CX, SI, R14
	MOVQ   AX, R15
	LEAQ   (DX)(R14*1), CX
	ROLQ   CL, R15
	BZHIQ  R14, R15, R15
	MOVQ   CX, DX
	MOVQ   SI, CX
	SHRQ   $0x20, CX
	ADDQ   R15, CX
	MOVQ   CX, (R9)

	// Fill bitreader for state updates
	MOVQ    R13, (SP)
	MOVQ    $0x00000808, CX
	BEXTRQ  CX, R8, R13
	CMPQ    32(SP), $0x00
	JZ      sequenceDecs_decode_bmi2_skip_update
	LEAQ    (SI)(DI*1), R14
	ADDQ    R8, R14
	MOVBQZX R14, R14
	LEAQ    (DX)(R14*1), CX
	MOVQ    AX, R15
	MOVQ    CX, DX
	ROLQ    CL, R15
	BZHIQ   R14, R15, R15

	// Update Offset State
	BZHIQ R8, R15, CX
	SHRXQ R8, R15, R15
	SHRL  $0x10, R8
	ADDQ  CX, R8

	// Load ctx.ofTable
	MOVQ 24(SP), CX
	MOVQ (CX)(R8*8), R8

	// Update Match Length State
	BZHIQ DI, R15, CX
	SHRXQ DI, R15, R15
	SHRL  $0x10, DI
	ADDQ  CX, DI

	// Load ctx.mlTable
	MOVQ 16(SP), CX
	MOVQ (CX)(DI*8), DI

	// Update Literal Length State
	BZHIQ SI, R15, CX
	SHRL  $0x10, SI
	ADDQ  CX, SI

	// Load ctx.llTable
	MOVQ 8(SP), CX
	MOVQ (CX)(SI*8), SI

sequenceDecs_decode_bmi2_skip_update:
	// Adjust offset
	MOVQ 16(R9), CX
	CMPQ R13, $0x01
	JBE  sequenceDecs_decode_bmi2_adjust_offsetB_1_or_0
	MOVQ R11, R12
	MOVQ R10, R11
	MOVQ CX, R10
	JMP  sequenceDecs_decode_bmi2_after_adjust

sequenceDecs_decode_bmi2_adjust_offsetB_1_or_0:
	CMPQ (R9), $0x00000000
	JNE  sequenceDecs_decode_bmi2_adjust_offset_maybezero
	INCQ CX
	JMP  sequenceDecs_decode_bmi2_adjust_offset_nonzero

sequenceDecs_decode_bmi2_adjust_offset_maybezero:
	TESTQ CX, CX
	JNZ   sequenceDecs_decode_bmi2_adjust_offset_nonzero
	MOVQ  R10, CX
	JMP   sequenceDecs_decode_bmi2_after_adjust

sequenceDecs_decode_bmi2_adjust_offset_nonzero:
	CMPQ CX, $0x01
	JB   sequenceDecs_decode_bmi2_adjust_zero
	JEQ  sequenceDecs_decode_bmi2_adjust_one
	CMPQ CX, $0x02
	JA   sequenceDecs_decode_bmi2_adjust_three
	JMP  sequenceDecs_decode_bmi2_adjust_two

sequenceDecs_decode_bmi2_adjust_zero:
	MOVQ R10, R13
	JMP  sequenceDecs_decode_bmi2_adjust_test_temp_valid

sequenceDecs_decode_bmi2_adjust_one:
	MOVQ R11, R13
	JMP  sequenceDecs_decode_bmi2_adjust_test_temp_valid

sequenceDecs_decode_bmi2_adjust_two:
	MOVQ R12, R13
	JMP  sequenceDecs_decode_bmi2_adjust_test_temp_valid

sequenceDecs_decode_bmi2_adjust_three:
	LEAQ -1(R10), R13

sequenceDecs_decode_bmi2_adjust_test_temp_valid:
	TESTQ R13, R13
	JNZ   sequenceDecs_decode_bmi2_adjust_temp_valid
	MOVQ  $0x00000001, R13

sequenceDecs_decode_bmi2_adjust_temp_valid:
	CMPQ    CX, $0x01
	CMOVQNE R11, R12
	MOVQ    R10, R11
	MOVQ    R13, R10
	MOVQ    R13, CX

sequenceDecs_decode_bmi2_after_adjust:
	MOVQ CX, 16(R9)

	// Check values
	MOVQ  8(R9), R13
	MOVQ  (R9), R14
	LEAQ  (R13)(R14*1), R15
	MOVQ  s+0(FP), BP
	ADDQ  R15, 256(BP)
	MOVQ  ctx+16(FP), R15
	SUBQ  R14, 128(R15)
	JS    error_not_enough_literals
	CMPQ  R13, $0x00020002
	JA    sequenceDecs_decode_bmi2_error_match_len_too_big
	TESTQ CX, CX
	JNZ   sequenceDecs_decode_bmi2_match_len_ofs_ok
	TESTQ R13, R13
	JNZ   sequenceDecs_decode_bmi2_error_match_len_ofs_mismatch

sequenceDecs_decode_bmi2_match_len_ofs_ok:
	ADDQ $0x18, R9
	DECQ 32(SP)
	JNS  sequenceDecs_decode_bmi2_main_loop
	MOVQ s+0(FP), CX
	MOVQ R10, 144(CX)
	MOVQ R11, 152(CX)
	MOVQ R12, 160(CX)
	MOVQ br+8(FP), CX
	MOVQ AX, 24(CX)
	MOVB DL, 40(CX)
	MOVQ BX, 32(CX)

	// Return success
	MOVQ 32(SP), AX
	MOVQ ctx+16(FP), CX
	MOVQ AX, 96(CX)
	MOVQ $0x00000000, ret+24(FP)
	RET

	// Return with match length error
sequenceDecs_decode_bmi2_error_match_len_ofs_mismatch:
	MOVQ 32(SP), AX
	MOVQ ctx+16(FP), CX
	MOVQ AX, 96(CX)
	MOVQ $0x00000001, ret+24(FP)
	RET

	// Return with match too long error
sequenceDecs_decode_bmi2_error_match_len_too_big:
	MOVQ 32(SP), AX
	MOVQ ctx+16(FP), CX
	MOVQ AX, 96(CX)
	MOVQ $0x00000002, ret+24(FP)
	RET

	// Return with match offset too long error
	MOVQ 32(SP), AX
	MOVQ ctx+16(FP), CX
	MOVQ AX, 96(CX)
	MOVQ $0x00000003, ret+24(FP)
	RET

	// Return with not enough literals error
error_not_enough_literals:
	MOVQ 32(SP), AX
	MOVQ ctx+16(FP), CX
	MOVQ AX, 96(CX)
	MOVQ $0x00000004, ret+24(FP)
	RET

	// Return with overread error
error_overread:
	MOVQ 32(SP), AX
	MOVQ ctx+16(FP), CX
	MOVQ AX, 96(CX)
	MOVQ $0x00000006, ret+24(FP)
	RET

// func sequenceDecs_decode_56_bmi2(s *sequenceDecs, br *bitReader, ctx *decodeAsmContext) int
// Requires: BMI, BMI2, CMOV
TEXT ·sequenceDecs_decode_56_bmi2(SB), $40-32
	MOVQ    br+8(FP), BX
	MOVQ    24(BX), AX
	MOVBQZX 40(BX), DX
	MOVQ    (BX), CX
	MOVQ    32(BX), BX
	ADDQ    BX, CX
	MOVQ    CX, (SP)
	MOVQ    ctx+16(FP), CX
	MOVQ    72(CX), SI
	MOVQ    80(CX), DI
	MOVQ    88(CX), R8
	MOVQ    (CX), R9
	MOVQ    R9, 8(SP)
	MOVQ    24(CX), R9
	MOVQ    R9, 16(SP)
	MOVQ    48(CX), R9
	MOVQ    R9, 24(SP)
	MOVQ    96(CX), R9
	MOVQ    R9, 32(SP)
	MOVQ    104(CX), R9
	MOVQ    s+0(FP), CX
	MOVQ    144(CX), R10
	MOVQ    152(CX), R11
	MOVQ    160(CX), R12
	PCALIGN $0x40

sequenceDecs_decode_56_bmi2_main_loop:
	MOVQ (SP), R13

	// Fill bitreader to have enough for the offset and match length.
	CMPQ BX, $0x08
	JL   sequenceDecs_decode_56_bmi2_fill_byte_by_byte
	MOVQ DX, CX
	SHRQ $0x03, CX
	SUBQ CX, R13
	MOVQ (R13), AX
	SUBQ CX, BX
	ANDQ $0x07, DX
	JMP  sequenceDecs_decode_56_bmi2_fill_end

sequenceDecs_decode_56_bmi2_fill_byte_by_byte:
	CMPQ    BX, $0x00
	JLE     sequenceDecs_decode_56_bmi2_fill_check_overread
	CMPQ    DX, $0x07
	JLE     sequenceDecs_decode_56_bmi2_fill_end
	SHLQ    $0x08, AX
	SUBQ    $0x01, R13
	SUBQ    $0x01, BX
	SUBQ    $0x08, DX
	MOVBQZX (R13), CX
	ORQ     CX, AX
	JMP     sequenceDecs_decode_56_bmi2_fill_byte_by_byte

sequenceDecs_decode_56_bmi2_fill_check_overread:
	CMPQ DX, $0x40
	JA   error_overread

sequenceDecs_decode_56_bmi2_fill_end:
	// Update offset
	MOVQ   $0x00000808, CX
	BEXTRQ CX, R8, R14
	MOVQ   AX, R15
	LEAQ   (DX)(R14*1), CX
	ROLQ   CL, R15
	BZHIQ  R14, R15, R15
	MOVQ   CX, DX
	MOVQ   R8, CX
	SHRQ   $0x20, CX
	ADDQ   R15, CX
	MOVQ   CX, 16(R9)

	// Update match length
	MOVQ   $0x00000808, CX
	BEXTRQ CX, DI, R14
	MOVQ   AX, R15
	LEAQ   (DX)(R14*1), CX
	ROLQ   CL, R15
	BZHIQ  R14, R15, R15
	MOVQ   CX, DX
	MOVQ   DI, CX
	SHRQ   $0x20, CX
	ADDQ   R15, CX
	MOVQ   CX, 8(R9)

	// Update literal length
	MOVQ   $0x00000808, CX
	BEXTRQ CX, SI, R14
	MOVQ   AX, R15
	LEAQ   (DX)(R14*1), CX
	ROLQ   CL, R15
	BZHIQ  R14, R15, R15
	MOVQ   CX, DX
	MOVQ   SI, CX
	SHRQ   $0x20, CX
	ADDQ   R15, CX
	MOVQ   CX, (R9)

	// Fill bitreader for state updates
	MOVQ    R13, (SP)
	MOVQ    $0x00000808, CX
	BEXTRQ  CX, R8, R13
	CMPQ    32(SP), $0x00
	JZ      sequenceDecs_decode_56_bmi2_skip_update
	LEAQ    (SI)(DI*1), R14
	ADDQ    R8, R14
	MOVBQZX R14, R14
	LEAQ    (DX)(R14*1), CX
	MOVQ    AX, R15
	MOVQ    CX, DX
	ROLQ    CL, R15
	BZHIQ   R14, R15, R15

	// Update Offset State
	BZHIQ R8, R15, CX
	SHRXQ R8, R15, R15
	SHRL  $0x10, R8
	ADDQ  CX, R8

	// Load ctx.ofTable
	MOVQ 24(SP), CX
	MOVQ (CX)(R8*8), R8

	// Update Match Length State
	BZHIQ DI, R15, CX
	SHRXQ DI, R15, R15
	SHRL  $0x10, DI
	ADDQ  CX, DI

	// Load ctx.mlTable
	MOVQ 16(SP), CX
	MOVQ (CX)(DI*8), DI

	// Update Literal Length State
	BZHIQ SI, R15, CX
	SHRL  $0x10, SI
	ADDQ  CX, SI

	// Load ctx.llTable
	MOVQ 8(SP), CX
	MOVQ (CX)(SI*8), SI

sequenceDecs_decode_56_bmi2_skip_update:
	// Adjust offset
	MOVQ 16(R9), CX
	CMPQ R13, $0x01
	JBE  sequenceDecs_decode_56_bmi2_adjust_offsetB_1_or_0
	MOVQ R11, R12
	MOVQ R10, R11
	MOVQ CX, R10
	JMP  sequenceDecs_decode_56_bmi2_after_adjust

sequenceDecs_decode_56_bmi2_adjust_offsetB_1_or_0:
	CMPQ (R9), $0x00000000
	JNE  sequenceDecs_decode_56_bmi2_adjust_offset_maybezero
	INCQ CX
	JMP  sequenceDecs_decode_56_bmi2_adjust_offset_nonzero

sequenceDecs_decode_56_bmi2_adjust_offset_maybezero:
	TESTQ CX, CX
	JNZ   sequenceDecs_decode_56_bmi2_adjust_offset_nonzero
	MOVQ  R10, CX
	JMP   sequenceDecs_decode_56_bmi2_after_adjust

sequenceDecs_decode_56_bmi2_adjust_offset_nonzero:
	CMPQ CX, $0x01
	JB   sequenceDecs_decode_56_bmi2_adjust_zero
	JEQ  sequenceDecs_decode_56_bmi2_adjust_one
	CMPQ CX, $0x02
	JA   sequenceDecs_decode_56_bmi2_adjust_three
	JMP  sequenceDecs_decode_56_bmi2_adjust_two

sequenceDecs_decode_56_bmi2_adjust_zero:
	MOVQ R10, R13
	JMP  sequenceDecs_decode_56_bmi2_adjust_test_temp_valid

sequenceDecs_decode_56_bmi2_adjust_one:
	MOVQ R11, R13
	JMP  sequenceDecs_decode_56_bmi2_adjust_test_temp_valid

sequenceDecs_decode_56_bmi2_adjust_two:
	MOVQ R12, R13
	JMP  sequenceDecs_decode_56_bmi2_adjust_test_temp_valid

sequenceDecs_decode_56_bmi2_adjust_three:
	LEAQ -1(R10), R13

sequenceDecs_decode_56_bmi2_adjust_test_temp_valid:
	TESTQ R13, R13
	JNZ   sequenceDecs_decode_56_bmi2_adjust_temp_valid
	MOVQ  $0x00000001, R13

sequenceDecs_decode_56_bmi2_adjust_temp_valid:
	CMPQ    CX, $0x01
	CMOVQNE R11, R12
	MOVQ    R10, R11
	MOVQ    R13, R10
	MOVQ    R13, CX

sequenceDecs_decode_56_bmi2_after_adjust:
	MOVQ CX, 16(R9)

	// Check values
	MOVQ  8(R9), R13
	MOVQ  (R9), R14
	LEAQ  (R13)(R14*1), R15
	MOVQ  s+0(FP), BP
	ADDQ  R15, 256(BP)
	MOVQ  ctx+16(FP), R15
	SUBQ  R14, 128(R15)
	JS    error_not_enough_literals
	CMPQ  R13, $0x00020002
	JA    sequenceDecs_decode_56_bmi2_error_match_len_too_big
	TESTQ CX, CX
	JNZ   sequenceDecs_decode_56_bmi2_match_len_ofs_ok
	TESTQ R13, R13
	JNZ   sequenceDecs_decode_56_bmi2_error_match_len_ofs_mismatch

sequenceDecs_decode_56_bmi2_match_len_ofs_ok:
	ADDQ $0x18, R9
	DECQ 32(SP)
	JNS  sequenceDecs_decode_56_bmi2_main_loop
	MOVQ s+0(FP), CX
	MOVQ R10, 144(CX)
	MOVQ R11, 152(CX)
	MOVQ R12, 160(CX)
	MOVQ br+8(FP), CX
	MOVQ AX, 24(CX)
	MOVB DL, 40(CX)
	MOVQ BX, 32(CX)

	// Return success
	MOVQ 32(SP), AX
	MOVQ ctx+16(FP), CX
	MOVQ AX, 96(CX)
	MOVQ $0x00000000, ret+24(FP)
	RET

	// Return with match length error
sequenceDecs_decode_56_bmi2_error_match_len_ofs_mismatch:
	MOVQ 32(SP), AX
	MOVQ ctx+16(FP), CX
	MOVQ AX, 96(CX)
	MOVQ $0x00000001, ret+24(FP)
	RET

	// Return with match too long error
sequenceDecs_decode_56_bmi2_error_match_len_too_big:
	MOVQ 32(SP), AX
	MOVQ ctx+16(FP), CX
	MOVQ AX, 96(CX)
	MOVQ $0x00000002, ret+24(FP)
	RET

	// Return with match offset too long error
	MOVQ 32(SP), AX
	MOVQ ctx+16(FP), CX
	MOVQ AX, 96(CX)
	MOVQ $0x00000003, ret+24(FP)
	RET

	// Return with not enough literals error
error_not_enough_literals:
	MOVQ 32(SP), AX
	MOVQ ctx+16(FP), CX
	MOVQ AX, 96(CX)
	MOVQ $0x00000004, ret+24(FP)
	RET

	// Return with overread error
error_overread:
	MOVQ 32(SP), AX
	MOVQ ctx+16(FP), CX
	MOVQ AX, 96(CX)
	MOVQ $0x00000006, ret+24(FP)
	RET

// func sequenceDecs_executeSimple_amd64(ctx *executeAsmContext) bool
// Requires: MMX+, SSE
TEXT ·sequenceDecs_executeSimple_amd64(SB), $32-9
	MOVQ  ctx+0(FP), R10
	MOVQ  8(R10), CX
	TESTQ CX, CX
	JZ    empty_seqs
	MOVQ  (R10), AX

	// seqsEnd = seqsBase + 24 * len(seqs) if ctx.prefetch, else seqsBase (prefetch off)
	MOVQ    AX, DX
	MOVBQZX 128(R10), R11
	TESTQ   R11, R11
	JZ      prefetch_off
	LEAQ    (CX)(CX*2), DX
	SHLQ    $0x03, DX
	ADDQ    AX, DX

prefetch_off:
	MOVQ DX, (SP)
	MOVQ 24(R10), DX
	MOVQ 32(R10), BX
	MOVQ 80(R10), SI
	MOVQ 104(R10), DI
	MOVQ 120(R10), R8
	MOVQ 56(R10), R9
	MOVQ 64(R10), R10
	ADDQ R10, R9

	// seqsBase += 24 * seqIndex
	LEAQ (DX)(DX*2), R11
	SHLQ $0x03, R11
	ADDQ R11, AX

	// outBase += outPosition
	ADDQ DI, BX
	MOVQ BX, 8(SP)
	MOVQ BX, R11
	SUBQ DI, R11
	MOVQ R11, 16(SP)
	NEGQ R11
	ADDQ R9, R11
	MOVQ R11, 24(SP)

	// Prime the prefetch window
	MOVQ (SP), R11
	LEAQ (AX), R12
	CMPQ R12, R11
	JAE  prefetch_skip_0
	MOVQ 8(SP), R12
	MOVQ (AX), R11
	ADDQ R11, R12
	MOVQ R12, R13
	MOVQ 16(AX), R11
	SUBQ R11, R13
	MOVQ 16(SP), R11
	CMPQ R13, R11
	JAE  prefetch_in_out_0
	MOVQ 24(SP), R11
	ADDQ R11, R13

prefetch_in_out_0:
	PREFETCHT0 (R13)
	PREFETCHT0 64(R13)
	MOVQ       8(AX), R11
	ADDQ       R11, R12
	MOVQ       R12, 8(SP)

prefetch_skip_0:
	MOVQ (SP), R11
	LEAQ 24(AX), R12
	CMPQ R12, R11
	JAE  prefetch_skip_1
	MOVQ 8(SP), R12
	MOVQ 24(AX), R11
	ADDQ R11, R12
	MOVQ R12, R13
	MOVQ 40(AX), R11
	SUBQ R11, R13
	MOVQ 16(SP), R11
	CMPQ R13, R11
	JAE  prefetch_in_out_1
	MOVQ 24(SP), R11
	ADDQ R11, R13

prefetch_in_out_1:
	PREFETCHT0 (R13)
	PREFETCHT0 64(R13)
	MOVQ       32(AX), R11
	ADDQ       R11, R12
	MOVQ       R12, 8(SP)

prefetch_skip_1:
	MOVQ (SP), R11
	LEAQ 48(AX), R12
	CMPQ R12, R11
	JAE  prefetch_skip_2
	MOVQ 8(SP), R12
	MOVQ 48(AX), R11
	ADDQ R11, R12
	MOVQ R12, R13
	MOVQ 64(AX), R11
	SUBQ R11, R13
	MOVQ 16(SP), R11
	CMPQ R13, R11
	JAE  prefetch_in_out_2
	MOVQ 24(SP), R11
	ADDQ R11, R13

prefetch_in_out_2:
	PREFETCHT0 (R13)
	PREFETCHT0 64(R13)
	MOVQ       56(AX), R11
	ADDQ       R11, R12
	MOVQ       R12, 8(SP)

prefetch_skip_2:
	MOVQ (SP), R11
	LEAQ 72(AX), R12
	CMPQ R12, R11
	JAE  prefetch_skip_3
	MOVQ 8(SP), R12
	MOVQ 72(AX), R11
	ADDQ R11, R12
	MOVQ R12, R13
	MOVQ 88(AX), R11
	SUBQ R11, R13
	MOVQ 16(SP), R11
	CMPQ R13, R11
	JAE  prefetch_in_out_3
	MOVQ 24(SP), R11
	ADDQ R11, R13

prefetch_in_out_3:
	PREFETCHT0 (R13)
	PREFETCHT0 64(R13)
	MOVQ       80(AX), R11
	ADDQ       R11, R12
	MOVQ       R12, 8(SP)

prefetch_skip_3:
	MOVQ (SP), R11
	LEAQ 96(AX), R12
	CMPQ R12, R11
	JAE  prefetch_skip_4
	MOVQ 8(SP), R12
	MOVQ 96(AX), R11
	ADDQ R11, R12
	MOVQ R12, R13
	MOVQ 112(AX), R11
	SUBQ R11, R13
	MOVQ 16(SP), R11
	CMPQ R13, R11
	JAE  prefetch_in_out_4
	MOVQ 24(SP), R11
	ADDQ R11, R13

prefetch_in_out_4:
	PREFETCHT0 (R13)
	PREFETCHT0 64(R13)
	MOVQ       104(AX), R11
	ADDQ       R11, R12
	MOVQ       R12, 8(SP)

prefetch_skip_4:
	MOVQ (SP), R11
	LEAQ 120(AX), R12
	CMPQ R12, R11
	JAE  prefetch_skip_5
	MOVQ 8(SP), R12
	MOVQ 120(AX), R11
	ADDQ R11, R12
	MOVQ R12, R13
	MOVQ 136(AX), R11
	SUBQ R11, R13
	MOVQ 16(SP), R11
	CMPQ R13, R11
	JAE  prefetch_in_out_5
	MOVQ 24(SP), R11
	ADDQ R11, R13

prefetch_in_out_5:
	PREFETCHT0 (R13)
	PREFETCHT0 64(R13)
	MOVQ       128(AX), R11
	ADDQ       R11, R12
	MOVQ       R12, 8(SP)

prefetch_skip_5:
	MOVQ (SP), R11
	LEAQ 144(AX), R12
	CMPQ R12, R11
	JAE  prefetch_skip_6
	MOVQ 8(SP), R12
	MOVQ 144(AX), R11
	ADDQ R11, R12
	MOVQ R12, R13
	MOVQ 160(AX), R11
	SUBQ R11, R13
	MOVQ 16(SP), R11
	CMPQ R13, R11
	JAE  prefetch_in_out_6
	MOVQ 24(SP), R11
	ADDQ R11, R13

prefetch_in_out_6:
	PREFETCHT0 (R13)
	PREFETCHT0 64(R13)
	MOVQ       152(AX), R11
	ADDQ       R11, R12
	MOVQ       R12, 8(SP)

prefetch_skip_6:
	MOVQ (SP), R11
	LEAQ 168(AX), R12
	CMPQ R12, R11
	JAE  prefetch_skip_7
	MOVQ 8(SP), R12
	MOVQ 168(AX), R11
	ADDQ R11, R12
	MOVQ R12, R13
	MOVQ 184(AX), R11
	SUBQ R11, R13
	MOVQ 16(SP), R11
	CMPQ R13, R11
	JAE  prefetch_in_out_7
	MOVQ 24(SP), R11
	ADDQ R11, R13

prefetch_in_out_7:
	PREFETCHT0 (R13)
	PREFETCHT0 64(R13)
	MOVQ       176(AX), R11
	ADDQ       R11, R12
	MOVQ       R12, 8(SP)
	PCALIGN    $0x40

prefetch_skip_7:
main_loop:
	MOVQ (SP), R11
	LEAQ 192(AX), R12
	CMPQ R12, R11
	JAE  prefetch_skip_8
	MOVQ 8(SP), R12
	MOVQ 192(AX), R11
	ADDQ R11, R12
	MOVQ R12, R13
	MOVQ 208(AX), R11
	SUBQ R11, R13
	MOVQ 16(SP), R11
	CMPQ R13, R11
	JAE  prefetch_in_out_8
	MOVQ 24(SP), R11
	ADDQ R11, R13

prefetch_in_out_8:
	PREFETCHT0 (R13)
	PREFETCHT0 64(R13)
	MOVQ       200(AX), R11
	ADDQ       R11, R12
	MOVQ       R12, 8(SP)

prefetch_skip_8:
	MOVQ (AX), R11
	MOVQ 16(AX), R12
	MOVQ 8(AX), R13

	// Copy literals
	MOVUPS (SI), X0
	MOVUPS X0, (BX)
	CMPQ   R11, $0x10
	JBE    copy_1_end
	MOVQ   $0x00000010, R14

copy_1:
	MOVUPS (SI)(R14*1), X0
	MOVUPS X0, (BX)(R14*1)
	ADDQ   $0x10, R14
	CMPQ   R14, R11
	JB     copy_1

copy_1_end:
	ADDQ R11, SI
	ADDQ R11, BX
	ADDQ R11, DI

	// Malformed input if seq.mo > t+len(hist) || seq.mo > s.windowSize)
	LEAQ (DI)(R10*1), R11
	CMPQ R12, R11
	JG   error_match_off_too_big
	CMPQ R12, R8
	JG   error_match_off_too_big

	// Copy match from history
	MOVQ R12, R11
	SUBQ DI, R11
	JLS  copy_match
	MOVQ R9, R14
	SUBQ R11, R14
	CMPQ R13, R11
	JG   copy_all_from_history
	MOVQ R13, R11
	SUBQ $0x10, R11
	JB   copy_4_small

copy_4_loop:
	MOVUPS (R14), X0
	MOVUPS X0, (BX)
	ADDQ   $0x10, R14
	ADDQ   $0x10, BX
	SUBQ   $0x10, R11
	JAE    copy_4_loop
	LEAQ   16(R14)(R11*1), R14
	LEAQ   16(BX)(R11*1), BX
	MOVUPS -16(R14), X0
	MOVUPS X0, -16(BX)
	JMP    copy_4_end

copy_4_small:
	CMPQ R13, $0x03
	JE   copy_4_move_3
	CMPQ R13, $0x08
	JB   copy_4_move_4through7
	JMP  copy_4_move_8through16

copy_4_move_3:
	MOVWQZX (R14), R11
	MOVB    2(R14), R12
	MOVW    R11, (BX)
	MOVB    R12, 2(BX)
	ADDQ    R13, R14
	ADDQ    R13, BX
	JMP     copy_4_end

copy_4_move_4through7:
	MOVL (R14), R11
	MOVL -4(R14)(R13*1), R12
	MOVL R11, (BX)
	MOVL R12, -4(BX)(R13*1)
	ADDQ R13, R14
	ADDQ R13, BX
	JMP  copy_4_end

copy_4_move_8through16:
	MOVQ (R14), R11
	MOVQ -8(R14)(R13*1), R12
	MOVQ R11, (BX)
	MOVQ R12, -8(BX)(R13*1)
	ADDQ R13, R14
	ADDQ R13, BX

copy_4_end:
	ADDQ R13, DI
	ADDQ $0x18, AX
	INCQ DX
	CMPQ DX, CX
	JB   main_loop
	JMP  loop_finished

copy_all_from_history:
	MOVQ R11, R15
	SUBQ $0x10, R15
	JB   copy_5_small

copy_5_loop:
	MOVUPS (R14), X0
	MOVUPS X0, (BX)
	ADDQ   $0x10, R14
	ADDQ   $0x10, BX
	SUBQ   $0x10, R15
	JAE    copy_5_loop
	LEAQ   16(R14)(R15*1), R14
	LEAQ   16(BX)(R15*1), BX
	MOVUPS -16(R14), X0
	MOVUPS X0, -16(BX)
	JMP    copy_5_end

copy_5_small:
	CMPQ R11, $0x03
	JE   copy_5_move_3
	JB   copy_5_move_1or2
	CMPQ R11, $0x08
	JB   copy_5_move_4through7
	JMP  copy_5_move_8through16

copy_5_move_1or2:
	MOVB (R14), R15
	MOVB -1(R14)(R11*1), BP
	MOVB R15, (BX)
	MOVB BP, -1(BX)(R11*1)
	ADDQ R11, R14
	ADDQ R11, BX
	JMP  copy_5_end

copy_5_move_3:
	MOVWQZX (R14), R15
	MOVB    2(R14), BP
	MOVW    R15, (BX)
	MOVB    BP, 2(BX)
	ADDQ    R11, R14
	ADDQ    R11, BX
