copy_5_move_4through7:
	MOVL (R14), R15
	MOVL -4(R14)(R11*1), BP
	MOVL R15, (BX)
	MOVL BP, -4(BX)(R11*1)
	ADDQ R11, R14
	ADDQ R11, BX
	JMP  copy_5_end

copy_5_move_8through16:
	MOVQ (R14), R15
	MOVQ -8(R14)(R11*1), BP
	MOVQ R15, (BX)
	MOVQ BP, -8(BX)(R11*1)
	ADDQ R11, R14
	ADDQ R11, BX

copy_5_end:
	ADDQ R11, DI
	SUBQ R11, R13

	// Copy match from the current buffer
copy_match:
	MOVQ BX, R11
	SUBQ R12, R11

	// ml <= mo
	CMPQ R13, R12
	JA   copy_overlapping_match

	// Copy non-overlapping match
	ADDQ   R13, DI
	MOVUPS (R11), X0
	MOVUPS X0, (BX)
	CMPQ   R13, $0x10
	JA     copy_2_long
	ADDQ   R13, BX
	JMP    handle_loop

copy_2_long:
	LEAQ 16(BX), R12
	ADDQ R13, BX
	ADDQ $0x10, R11
	SUBQ $0x10, R13

copy_2:
	MOVUPS (R11), X0
	MOVUPS X0, (R12)
	ADDQ   $0x10, R11
	ADDQ   $0x10, R12
	SUBQ   $0x10, R13
	JHI    copy_2
	JMP    handle_loop

	// Copy overlapping match
copy_overlapping_match:
	ADDQ R13, DI
	CMPQ R12, $0x10
	JB   copy_slow_3
	MOVQ BX, R12
	ADDQ R13, BX

copy_3:
	MOVUPS (R11), X0
	MOVUPS X0, (R12)
	ADDQ   $0x10, R11
	ADDQ   $0x10, R12
	SUBQ   $0x10, R13
	JHI    copy_3
	JMP    handle_loop

copy_slow_3:
	MOVBQZX (R11), R12
	MOVB    R12, (BX)
	INCQ    R11
	INCQ    BX
	DECQ    R13
	JNZ     copy_slow_3

handle_loop:
	ADDQ $0x18, AX
	INCQ DX
	CMPQ DX, CX
	JB   main_loop

loop_finished:
	// Return value
	MOVB $0x01, ret+8(FP)

	// Update the context
	MOVQ ctx+0(FP), AX
	MOVQ DX, 24(AX)
	MOVQ DI, 104(AX)
	SUBQ 80(AX), SI
	MOVQ SI, 112(AX)
	RET

error_match_off_too_big:
	// Return value
	MOVB $0x00, ret+8(FP)

	// Update the context
	MOVQ ctx+0(FP), AX
	MOVQ DX, 24(AX)
	MOVQ DI, 104(AX)
	SUBQ 80(AX), SI
	MOVQ SI, 112(AX)
	RET

empty_seqs:
	// Return value
	MOVB $0x01, ret+8(FP)
	RET

// func sequenceDecs_executeSimple_safe_amd64(ctx *executeAsmContext) bool
// Requires: MMX+, SSE
TEXT ·sequenceDecs_executeSimple_safe_amd64(SB), $32-9
	MOVQ  ctx+0(FP), R10
	MOVQ  8(R10), CX
	TESTQ CX, CX
	JZ    empty_seqs
	MOVQ  (R10), AX

	// seqsEnd = seqsBase + 24 * len(seqs) if ctx.prefetch, else seqsBase (prefetch off)
	MOVQ    AX, DX
	MOVBQZX 128(R10), R11
	TESTQ   R11, R11
	JZ      prefetch_off
	LEAQ    (CX)(CX*2), DX
	SHLQ    $0x03, DX
	ADDQ    AX, DX

prefetch_off:
	MOVQ DX, (SP)
	MOVQ 24(R10), DX
	MOVQ 32(R10), BX
	MOVQ 80(R10), SI
	MOVQ 104(R10), DI
	MOVQ 120(R10), R8
	MOVQ 56(R10), R9
	MOVQ 64(R10), R10
	ADDQ R10, R9

	// seqsBase += 24 * seqIndex
	LEAQ (DX)(DX*2), R11
	SHLQ $0x03, R11
	ADDQ R11, AX

	// outBase += outPosition
	ADDQ DI, BX
	MOVQ BX, 8(SP)
	MOVQ BX, R11
	SUBQ DI, R11
	MOVQ R11, 16(SP)
	NEGQ R11
	ADDQ R9, R11
	MOVQ R11, 24(SP)

	// Prime the prefetch window
	MOVQ (SP), R11
	LEAQ (AX), R12
	CMPQ R12, R11
	JAE  prefetch_skip_0
	MOVQ 8(SP), R12
	MOVQ (AX), R11
	ADDQ R11, R12
	MOVQ R12, R13
	MOVQ 16(AX), R11
	SUBQ R11, R13
	MOVQ 16(SP), R11
	CMPQ R13, R11
	JAE  prefetch_in_out_0
	MOVQ 24(SP), R11
	ADDQ R11, R13

prefetch_in_out_0:
	PREFETCHT0 (R13)
	PREFETCHT0 64(R13)
	MOVQ       8(AX), R11
	ADDQ       R11, R12
	MOVQ       R12, 8(SP)

prefetch_skip_0:
	MOVQ (SP), R11
	LEAQ 24(AX), R12
	CMPQ R12, R11
	JAE  prefetch_skip_1
	MOVQ 8(SP), R12
	MOVQ 24(AX), R11
	ADDQ R11, R12
	MOVQ R12, R13
	MOVQ 40(AX), R11
	SUBQ R11, R13
	MOVQ 16(SP), R11
	CMPQ R13, R11
	JAE  prefetch_in_out_1
	MOVQ 24(SP), R11
	ADDQ R11, R13

prefetch_in_out_1:
	PREFETCHT0 (R13)
	PREFETCHT0 64(R13)
	MOVQ       32(AX), R11
	ADDQ       R11, R12
	MOVQ       R12, 8(SP)

