	MOVQ 48(AX), R11
	ADDQ R11, R12
	MOVQ R12, R13
	MOVQ 64(AX), R11
	SUBQ R11, R13
	MOVQ 16(SP), R11
	CMPQ R13, R11
	JAE  prefetch_in_out_2
	MOVQ 24(SP), R11
	ADDQ R11, R13

prefetch_in_out_2:
	PREFETCHT0 (R13)
	PREFETCHT0 64(R13)
	MOVQ       56(AX), R11
	ADDQ       R11, R12
	MOVQ       R12, 8(SP)

prefetch_skip_2:
